100	std::string DuplexPipe::Read() {
101	  // Read the string from pipe
102	  std::string buf;
103	  // Read one line or multiple lines
104	  const int max_try_times = 3;
105	  int index = 0;
106	  while (1) {
107	    SetTimeOut();
108	    ssize_t size = read(fd2_[0], c_buf_, kBufferSize);  // MAYBE BLOCKED, Till reading something
109	    if (size <= 0) {
110	      if (errno == EINTR) {
111	        DP_WARNING << "Read was interrupted by system interrupt, retry: " << index;
112	        ++index;
113	        if (index == max_try_times) {
114	          DP_ERROR << "Read from pipe failed, try " << max_try_times << " times, reason = " << strerror(errno);
115	          break;
116	        }
117	        continue;
118	      }
119	      DP_ERROR << "Read from pipe failed, errno = " << errno << ", reason = " << strerror(errno);
120	      break;
121	    }
122	    CancelTimeOut();
123	    bool line_end = c_buf_[size - 1] == '\n';
124	    buf.append(c_buf_, LongToSize(line_end ? size - 1 : size));  // Copy without the last '\n'
125	    if (line_end) {
126	      break;
127	    }
128	  }
129	  return buf;
130	}
